   --trans-detached-bg: #FFF;
   --trans-detached-color: #1A1A1A;
   --trans-btn1: #B2B2B2;
/* ========================================================
   🔥 气泡文字大小穿透强制覆盖 (微信 1:1 终极微调)
   ======================================================== */
/* 1. 变量层兜底 */
:root {
  --bubble-me-font-size: 15.5px;
  --bubble-them-font-size: 15.5px;
}

/* 2. 深度穿透：下穿至内部 <p>、<span> 及文字节点，并排除特殊卡片 */
:is(.bubble-me-custom, .bubble-them-custom),
:is(.bubble-me-custom, .bubble-them-custom) p,
:is(.bubble-me-custom, .bubble-them-custom) > div:not(
    [class*="card"], [class*="card"] *, 
    .voice-msg, .voice-msg *, 
    .gift-ig-container, .gift-ig-container *,
    .msg-sim-card, .msg-sim-card *
),
:is(.bubble-me-custom, .bubble-them-custom) span:not(
    [class*="card"] *, 
    [class*="time"], 
    [class*="status"], 
    [class*="icon"],
    .voice-msg *
) {
    font-size: 15.5px !important;              /* 👈 核心：15.5px 完美居中 */
    line-height: 1.35 !important;              /* 微信标准行高，不臃肿也不紧贴 */
    letter-spacing: 0.15px !important;         /* 微信文字呼吸间距 */
    font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif !important;
    -webkit-font-smoothing: antialiased !important;
}

/* 3. 抹平 markdown 段落带来的上下多余空白 */
:is(.bubble-me-custom, .bubble-them-custom) p {
    margin: 0 !important;
    padding: 0 !important;
}
   /* === 我方气泡 === */
