/* 底栏毛玻璃与从上到下的自然排布 */
.input-area-custom {
    position: absolute !important;
    bottom: 0;
    width: 100%;
    z-index: 100;
    backdrop-filter: blur(28px) saturate(180%) !important;
    -webkit-backdrop-filter: blur(28px) saturate(180%) !important;
    padding-bottom: 33px !important;
    border-top: 0.5px solid rgba(0, 0, 0, 0.08) !important;
    display: flex !important;
    flex-direction: column !important; /* 👈 从上到下自然排布 */
}

/* ========================================================
   🎛️ 控制台、输入框、回复条的黄金位置与防遮挡机制
   ======================================================== */

/* 1. 控制台永远排在最上方（原本的位置） */
.nuo-console-shell {
    order: 1 !important;
    width: 100% !important;
}

/* 2. 输入框排在中间 */
.input-row-wrapper,
.input-action-bar-custom {
    order: 2 !important;
}

/* 3. 回复预览条排在输入框下方 */
.input-reply-preview-bar {
    order: 3 !important;
    position: relative !important;
    margin-left: 45px !important;
    margin-right: 77px !important;
    margin-top: 6px !important;
    margin-bottom: 2px !important;
    width: auto !important;
    height: 32px !important;
    min-height: 32px !important;
    background: #EAEAEA !important;
    border-radius: 6px !important;
    padding: 0 10px !important;
    border: none !important;
    box-shadow: none !important;
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important;
    justify-content: space-between !important;
    z-index: 10 !important;
}

/* 4. 防遮挡：彻底覆盖 控制台未展开、控制台展开、回复条 各种场景 */
/* ① 只要开启了控制台按钮条（哪怕没展开），消息列表就垫高 */
.chat-detail-screen:has(.nuo-console-shell) .chat-message-list-custom {
    padding-bottom: 135px !important;
}

/* ② 回复预览条弹出时垫高 */
.chat-detail-screen:has(.input-reply-preview-bar) .chat-message-list-custom {
    padding-bottom: 130px !important;
}

/* ③ 同时有控制台按钮 + 回复条时，进一步垫高 */
.chat-detail-screen:has(.nuo-console-shell):has(.input-reply-preview-bar) .chat-message-list-custom {
    padding-bottom: 180px !important;
}

/* ④ 点击展开控制台日志大面板时，留出大空间 */
.chat-detail-screen:has(.nuo-console-panel) .chat-message-list-custom {
    padding-bottom: 310px !important;
}

/* ========================================================
   ✅ 最终修复：“可按住 转文字”居中且绝不影响输入文字与发送键
   ======================================================== */

/* 1. 把胶囊上的 relative 恢复默认，保住你的右侧让位布局！ */
.input-action-bar-custom {
    position: static !important;
}

/* 2. 只有在 input-row-wrapper（整行输入栏）上挂 relative，
      它永远只包含【麦克风+输入框+右侧按钮】，高度固定，不会被上方的控制台/提示条撑跑！ */
.input-row-wrapper {
    position: relative !important;
}

/* 3. 精准锁定：居中在输入框区域，不向上飘，输入文字时自然消失 */
.input-row-wrapper:has(.input-box-custom:placeholder-shown)::before {
    content: "可按住 转文字" !important;
    position: absolute !important;
    left: 185px !important;              /* 居中在白色框内（微调 left 像素也可以，如 175px） */
    top: 20px !important;               /* 行内 50% 垂直居中，绝不飘去控制台 */
    transform: translate(-50%, -50%) !important;
    font-size: 13px !important;
    color: rgba(0, 0, 0, 0.35) !important;
    pointer-events: none !important;
    letter-spacing: 0.5px !important;
    white-space: nowrap !important;
    z-index: 5 !important;
}

/* 4. 回复预览条弹出时隐藏 */
.input-area-custom:has(.input-reply-preview-bar) .input-row-wrapper::before {
    display: none !important;
}

/* 5. 暗色模式文字颜色 */
@media (prefers-color-scheme: dark) {
    .input-row-wrapper:has(.input-box-custom:placeholder-shown)::before {
        color: rgba(255, 255, 255, 0.35) !important;
    }
}

/* 胶囊外壳结构 */
