/* ========================================================
   👥 微信群聊 1:1 完美适配补丁 (头像、备注、不合并)
   ======================================================== */

/* 1. 彻底斩杀各种花哨的群头衔、等级徽章，只留名字 */
.grp-title-badge {
    display: none !important;
}
/* 👈 彻底抹杀我方发言人备注行（微信我方绝对不显示名字） */
.grp-sender-row-me,
.msg-me .grp-sender-row {
    display: none !important;
}

/* 顺便抹掉我方头像可能残留的顶间距，让气泡和我方头像严丝合缝顶格对齐 */
.msg-avatar-me-container {
    margin-top: 0 !important;
}
/* 2. 打破连发合并机制：每一条都是独立消息，严格保持 15px 行间距 */
.msg-bubble-wrapper {
    margin-bottom: 15px !important;
}

/* 3. 强制显示所有对方头像（破解连发时自动隐藏头像的机制） */
.chat-detail-screen .msg-avatar-them-container {
    display: block !important;
    visibility: visible !important;
    opacity: 1 !important;

    /* 👈 核心：去掉系统的头像下移，让头像顶部与名字对齐！ */
    margin-top: 0 !important; 
}

/* 4. 头像圆角对齐（保持微信的 5px 方形圆角） */
.msg-avatar-them-container img,
.grp-intro-avatar img {
    border-radius: 5px !important;
}

/* ========================================================
   🎛️ 群聊成员备注开关 (高级自选功能)
   ======================================================== */
:root {
    /* 👇 在这里切换群成员备注的显示状态！
       👉 填 flex : 显示备注（气泡下沉，适合偶尔单发的群）
       👉 填 none : 隐藏备注（只留头像+气泡，完美齐平，极度干净！） */
    --show-group-nickname: none;   
}

/* 5. 备注名字排版（由上面的开关全局控制） */
.grp-sender-row {
    display: var(--show-group-nickname) !important;  /* 👈 核心：监听变量开关 */
    margin-bottom: 3px !important;       
    margin-top: -3px !important;         
    font-weight: normal !important;
    align-items: center !important;
}

/* 微信经典浅灰备注名 */
.grp-sender-name {
    font-size: 12px !important;
    font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif !important;
    color: #8E8E93 !important;           
    margin-left: 2px !important;
    line-height: 1.2 !important;
}

/* 6. 尖角位置校准（因为气泡下沉了，尖角就跟着气泡往下走，不要错位） */
:is(.bubble-me-custom, .bubble-them-custom)::after {
    top: 15px !important;                /* 固定在气泡右上/左上方 */
