.bubble-them-custom:has(.gift-ig-container)::after,
.bubble-them-custom:has(.msg-sim-card)::before,
.bubble-them-custom:has(.msg-sim-card)::after,
.bubble-them-custom:has(.msg-loc-card)::before,
.bubble-them-custom:has(.msg-loc-card)::after,
