  background-repeat: no-repeat !important;
}

/* 3. 🔥【关键优化】：精准切换逻辑 */

/* ① 当发送键出现时，隐藏 AI 灰锁（避免双按钮） */
.input-row-wrapper:has(.send-btn-custom) .input-btn-ai {
  display: none !important;
}

/* ② 仅当输入框【明确存在文字/拼音】且系统发送键未挂载的缝隙中，进行无缝伪装变蓝 */
/* 注意：这里去掉了 :focus，没打字点进输入框时依然保持高级的灰色闭合锁！ */
.input-row-wrapper:has(.input-box-custom:not(:placeholder-shown)) .input-btn-ai {
