  box-shadow: 0 1px 4px rgba(255, 59, 48, 0.4) !important;
}

/* =========================================================
   【补丁：纯净表情包/图片 (精准隔离版·绝不误杀正常文本尾巴)】感谢池渝的源代码，基于原来的基础上加上去掉小尾巴伪元素
   ========================================================= */

/* 1. 仅当“气泡本体内部”直接装了图片时，才精准掐灭这个气泡自己的尾巴 (绝不污染其他消息) */
.bubble-me-custom:has(.msg-image-wrapper)::before,
.bubble-me-custom:has(.msg-image-wrapper)::after,
.bubble-them-custom:has(.msg-image-wrapper)::before,
.bubble-them-custom:has(.msg-image-wrapper)::after,
.bubble-me-custom:has(img:not([class*="reply"] img))::before,
.bubble-me-custom:has(img:not([class*="reply"] img))::after,
.bubble-them-custom:has(img:not([class*="reply"] img))::before,
.bubble-them-custom:has(img:not([class*="reply"] img))::after {
  display: none !important;
  content: none !important;
  opacity: 0 !important;
  visibility: hidden !important;
}

/* 2. 仅当气泡内部装了图片时，该气泡外壳全透明、去内边距 */
.bubble-me-custom:has(.msg-image-wrapper),
.bubble-them-custom:has(.msg-image-wrapper),
.bubble-me-custom:has(img:not([class*="reply"] img)),
.bubble-them-custom:has(img:not([class*="reply"] img)) {
