  margin-right: auto !important;
  margin-left: 0 !important;
}

.msg-image-wrapper, 
.msg-bubble-container:has(img:not([class*="reply"] img)) {
  height: auto !important;
  min-height: 0 !important;
}

/* 4. 引用框内部的微缩正方形小图保持 28px */
div[class*="reply"] img,
.msg-reply-block-detached img,
.msg-reply-detached-text img {
